insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"numbers_advanced_q01_finish","speaker_external_id":"Little Boy","source_path":"_registry\\dialogues\\numbers_advanced_homework.yaml","source_metadata":{}},{"key":"numbers_advanced_q01_start","speaker_external_id":"Little Boy","source_path":"_registry\\dialogues\\numbers_advanced_homework.yaml","source_metadata":{}},{"key":"numbers_advanced_q02_finish","speaker_external_id":"Farmer","source_path":"_registry\\dialogues\\numbers_advanced_homework.yaml","source_metadata":{}},{"key":"numbers_advanced_q02_start","speaker_external_id":"Farmer","source_path":"_registry\\dialogues\\numbers_advanced_homework.yaml","source_metadata":{}},{"key":"numbers_advanced_q03_finish","speaker_external_id":"Professor Crazy","source_path":"_registry\\dialogues\\numbers_advanced_homework.yaml","source_metadata":{}},{"key":"numbers_advanced_q03_start","speaker_external_id":"Professor Crazy","source_path":"_registry\\dialogues\\numbers_advanced_homework.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"numbers_advanced_q01_finish","locale":"he","line_order":0,"content":"יש! החלק הראשון של המפה חזר למקום. עכשיו אני יודע לקרוא 10 עד 20.","line_format":"plain_text"},{"dialogue_key":"numbers_advanced_q01_finish","locale":"he","line_order":1,"content":"קחו את המפה ל־Farmer. בשוק חסרים השלטים של 20 עד 100.","line_format":"plain_text"},{"dialogue_key":"numbers_advanced_q01_start","locale":"he","line_order":0,"content":"אוי לא! מפת המספרים שלי התפרקה, ואני לא מצליח לסדר את החלק הראשון.","line_format":"plain_text"},{"dialogue_key":"numbers_advanced_q01_start","locale":"he","line_order":1,"content":"החלק הראשון מכיל את המספרים 10 עד 20. תעזרו לי למצוא את המילים החסרות.","line_format":"plain_text"},{"dialogue_key":"numbers_advanced_q01_start","locale":"he","line_order":2,"content":"קראו את ההוראות בעברית. באנגלית תראו רק את המילה שצריך ללמוד, כמו TEN.","line_format":"plain_text"},{"dialogue_key":"numbers_advanced_q02_finish","locale":"he","line_order":0,"content":"מצוין! השוק מסודר, והשלטים של 20 עד 100 ברורים לכולם.","line_format":"plain_text"},{"dialogue_key":"numbers_advanced_q02_finish","locale":"he","line_order":1,"content":"קחו את המפה ל־Professor Crazy. הוא שומר על המגדל של המאות.","line_format":"plain_text"},{"dialogue_key":"numbers_advanced_q02_start","locale":"he","line_order":0,"content":"ברוכים הבאים לשוק. הרוח פיזרה את שלטי העשרות בין הדוכנים.","line_format":"plain_text"},{"dialogue_key":"numbers_advanced_q02_start","locale":"he","line_order":1,"content":"סדרו את המספרים מ־20 עד 100, כדי שכל קונה ימצא את הדוכן הנכון.","line_format":"plain_text"},{"dialogue_key":"numbers_advanced_q02_start","locale":"he","line_order":2,"content":"המשימות בעברית, ובכל פעם נתרגל רק מילה או משפט קצר באנגלית.","line_format":"plain_text"},{"dialogue_key":"numbers_advanced_q03_finish","locale":"he","line_order":0,"content":"הצלחתם! מפת המספרים שלמה, ואתם יכולים לקרוא מספרים מ־10 עד 1000.","line_format":"plain_text"},{"dialogue_key":"numbers_advanced_q03_finish","locale":"he","line_order":1,"content":"זהו סיום שיעורי הבית Numbers Advanced. כל הכבוד על עבודה מדויקת!","line_format":"plain_text"},{"dialogue_key":"numbers_advanced_q03_start","locale":"he","line_order":0,"content":"הגעתם בזמן. במגדל נשאר החלק האחרון של המפה: 100 עד 1000.","line_format":"plain_text"},{"dialogue_key":"numbers_advanced_q03_start","locale":"he","line_order":1,"content":"נלמד את HUNDRED ואת THOUSAND, ונחבר אותם למספרים גדולים.","line_format":"plain_text"},{"dialogue_key":"numbers_advanced_q03_start","locale":"he","line_order":2,"content":"עבדו שלב־שלב: סדרו אותיות, סדרו משפטים ואמרו מספרים בקול.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
